const cleanText=v=>String(v??"").trim();
const escapeHtml=v=>cleanText(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;");
const toTextArray=v=>Array.isArray(v)?v.map(cleanText).filter(Boolean):(cleanText(v)?[cleanText(v)]:[]);
function uniqueText(values){const out=[],seen=new Set();for(const value of values||[]){const cleaned=cleanText(value);if(!cleaned)continue;const key=cleaned.toLowerCase();if(seen.has(key))continue;seen.add(key);out.push(cleaned);}return out;}
function normalizePlaycallingMode(value){const normalized=cleanText(value).toLowerCase();if(normalized===PLAYCALLING_MODE_TWO_MINUTE)return PLAYCALLING_MODE_TWO_MINUTE;if(normalized===PLAYCALLING_MODE_KILL_CLOCK)return PLAYCALLING_MODE_KILL_CLOCK;if(normalized===PLAYCALLING_MODE_COMEBACK)return PLAYCALLING_MODE_COMEBACK;if(normalized===PLAYCALLING_MODE_BLITZ_BEATER)return PLAYCALLING_MODE_BLITZ_BEATER;if(normalized===PLAYCALLING_MODE_REDZONE)return PLAYCALLING_MODE_REDZONE;return PLAYCALLING_MODE_NORMAL;}
function getPlaycallingModeMeta(mode){return PLAYCALLING_MODE_META[normalizePlaycallingMode(mode)]||PLAYCALLING_MODE_META[PLAYCALLING_MODE_NORMAL];}
function formatPlaycallingModeLabel(mode){return getPlaycallingModeMeta(mode).label;}
const MAX_GAME_SCORE=99,GAME_SCORE_MODE_DAMPEN=0.35,GAME_SCORE_ADJ_CAP=4.5,SCOREBOARD_DEBOUNCE_MS=450,SCOREBOARD_TRACE_DEBOUNCE_MS=2000;
const DEFENSE_LOG_OPTIONS=["Blitz","Man","Cover 1","Cover 2","Cover 3","Cover 4","Cover 6","Cover 9","Tampa 2"];
const SCORING_DEFENSE_UNKNOWN="Unknown";
const GAME_QUARTER_OT=5;
function normalizeQuarter(value){const raw=cleanText(value).toLowerCase();if(raw==="ot"||raw==="overtime")return GAME_QUARTER_OT;const n=Number(value);if(n===GAME_QUARTER_OT)return GAME_QUARTER_OT;if(n===2||n===3||n===4)return n;return 1;}
function isLateGameQuarter(quarter){const normalized=normalizeQuarter(quarter);return normalized===4||normalized===GAME_QUARTER_OT;}
function formatQuarterLabel(quarter=state.quarter){const normalized=normalizeQuarter(quarter);return normalized===GAME_QUARTER_OT?"OT":`Q${normalized}`;}
function formatScoreboardText(userScore=state.userScore,oppScore=state.oppScore,quarter=state.quarter){return`${formatQuarterLabel(quarter)} ${normalizeGameScore(userScore)}-${normalizeGameScore(oppScore)}`;}
function normalizeGameScore(value){const n=Number(value);if(!Number.isFinite(n))return 0;return Math.max(0,Math.min(MAX_GAME_SCORE,Math.round(n)));}
function getScoreDifferential(userScore=state.userScore,oppScore=state.oppScore){return normalizeGameScore(userScore)-normalizeGameScore(oppScore);}
function resetScoreboardState(){state.userScore=0;state.oppScore=0;state.quarter=1;if(state.scoreboardDebounceTimer){clearTimeout(state.scoreboardDebounceTimer);state.scoreboardDebounceTimer=null;}if(state.scoreboardTraceDebounceTimer){clearTimeout(state.scoreboardTraceDebounceTimer);state.scoreboardTraceDebounceTimer=null;}}
const hasKnownNumericValue=v=>v!==null&&v!==undefined&&v!==""&&Number.isFinite(Number(v));
function hexToRgb(hex){const n=cleanText(hex).replace("#","");if(n.length!==6)return{r:11,g:15,b:20};const value=parseInt(n,16);if(!Number.isFinite(value))return{r:11,g:15,b:20};return{r:(value>>16)&255,g:(value>>8)&255,b:value&255};}
