function canScoreDriveResult(recommendationSetKey=getRecommendationSetKey()){return ENABLE_DRIVE_RESULT_PICKER&&Boolean(state.confirmedRecommendationId)&&state.confirmedRecommendationSetKey===recommendationSetKey;}
function buildPreferencesPayload(){return{selectedTeam:state.selectedTeam,selectedOpponent:state.selectedOpponent,themeTeam:state.themeTeam,coordinatorRole:state.coordinatorRole===COORDINATOR_ROLE_DC?COORDINATOR_ROLE_DC:COORDINATOR_ROLE_OC,playcallingMode:state.playcallingMode};}
