function createTraceSessionHeader(reason="manual_reset",team=null){return["============================================================",`Gridiron OC trace session start: ${new Date().toISOString()}`,`reason: ${cleanText(reason)||"manual_reset"}`,`team: ${cleanText(team)||"not_selected"}`,"============================================================",""].join("\n");}
function formatTraceEventLine(tag,payload){return`LOG  [${cleanText(tag)||"trace"}] ${JSON.stringify(payload||{})}`;}
function formatRecommendationTraceBlock({at,transcript,situation,recommendations}){const lines=["","===== recommendation-trace =====",`time: ${at}`,`spoken: ${cleanText(transcript)||"(none)"}`,`situation: ${cleanText(situation?.label)||"(unknown)"}`,`team: ${cleanText(situation?.team)||"(none)"} | opponent: ${cleanText(situation?.opponent)||formatOpponentLabel(state.selectedOpponent)} | bucket: ${cleanText(situation?.distBucket)||"(unknown)"} | fieldBucket: ${cleanText(situation?.fieldPositionBucket)||"(unknown)"}`,`planner: goal=${cleanText(situation?.offensiveGoal)||"(unknown)"} | lean=${cleanText(situation?.runPassLean)||"(unknown)"} | risk=${cleanText(situation?.riskTolerance)||"(unknown)"} | pressure=${cleanText(situation?.pressureConcern)||"(unknown)"}`,`mode: ${cleanText(situation?.playcallingMode)||formatPlaycallingModeLabel(PLAYCALLING_MODE_NORMAL)}`,`scoreboard: ${cleanText(situation?.scoreboard)||formatScoreboardText()} | quarter: ${formatQuarterLabel(situation?.quarter??state.quarter)} | score: ${normalizeGameScore(situation?.userScore??state.userScore)}-${normalizeGameScore(situation?.oppScore??state.oppScore)} | diff: ${Number.isFinite(Number(situation?.scoreDiff))?Number(situation.scoreDiff):getScoreDifferential()}`,`keys: situation=${cleanText(situation?.situationKey)||"(none)"} | broad=${cleanText(situation?.broadSituationKey)||"(none)"} | learning=${cleanText(situation?.learningSituationKey)||"(none)"}`,`fieldPosition: ${formatTraceFieldPosition(situation?.fieldPosition)} | lastDefenseShown: ${formatLastDefenseShownLabel(situation?.lastDefenseShown??state.lastDefenseShown)} | defenseTendency: ${cleanText(situation?.activeDefenseTendency?.formationSetKey)||"none"} | scoringDefense: ${cleanText(situation?.defense)||SCORING_DEFENSE_UNKNOWN} | goalToGo: ${situation?.goalToGo?"yes":"no"}`,`scouting: observations=${Number(situation?.scoutingObservations)||0} | predictive=${normalizeDefenseLogValue(situation?.lastDefenseShown??state.lastDefenseShown)===SCORING_DEFENSE_UNKNOWN?"active":"off"}`];if(!Array.isArray(recommendations)||recommendations.length===0){lines.push("top recommendations: (none)");}else{lines.push("top recommendations:");recommendations.forEach(play=>{const scouting=Number.isFinite(Number(play.predict))?` | predict=${Number(play.predict).toFixed(2)} reactive=${Number(play.reactive).toFixed(2)} personal=${Number(play.personal).toFixed(2)}`:"";lines.push(`  ${play.rank}. score=${play.score} | ${play.type} | ${play.family} | ${play.formation} - ${play.set} - ${play.playName}${scouting}${play.scriptTag?` | script=${play.scriptTag}`:""}${play.scriptMatch?" | scriptMatch":""}${play.cooldownBlocked?" | cooldownBlocked":""}`);});}lines.push("================================");return lines.join("\n");}
function replaceTraceLogText(nextValue){state.traceLogText=pruneTraceLogText(nextValue);}
function appendTraceLogEntry(entry){const normalized=normalizeTraceText(entry).trimEnd();if(!normalized)return;const nextValue=state.traceLogText?`${state.traceLogText}${state.traceLogText.endsWith("\n")?"":"\n"}${normalized}\n`:`${normalized}\n`;replaceTraceLogText(nextValue);if(state.traceLogLoaded)window.desktopApi.writeTraceLog(state.traceLogText).catch(()=>{});}
function recordTraceBlock(block){appendTraceLogEntry(normalizeTraceText(block));}
function recordTraceEvent(tag,payload){appendTraceLogEntry(formatTraceEventLine(tag,payload));}
function resetTraceSession(reason="manual_reset"){replaceTraceLogText(createTraceSessionHeader(reason,state.selectedTeam));state.traceLogLoaded=true;window.desktopApi.writeTraceLog(state.traceLogText).catch(()=>{});}
async function exportTraceSession(){const message=normalizeTraceText(state.traceLogText).trim();if(!message)return;const result=await window.desktopApi.exportTraceLog(message);setStatus(result?.path?`Trace exported to ${result.path}`:"Trace export complete");}async function openTraceFolder(){const result=await window.desktopApi.openTraceFolder();setStatus(result?.path?`Opened trace folder: ${result.path}`:"Opened trace folder");}
function getTracePreviewText(){const normalized=normalizeTraceText(state.traceLogText);if(!normalized)return"No saved trace yet.";if(normalized.length<=TRACE_PREVIEW_CHARS)return normalized;return`[showing last ${TRACE_PREVIEW_CHARS} chars]\n\n${normalized.slice(-TRACE_PREVIEW_CHARS)}`;}
