const DefenseRecommendationCore=globalThis.GridironDefenseRecommendationCore||{};
function getDisplayedDcRecommendations(){return state.hasActiveSituation?state.presentedDcRecommendations:[];}
function getDcOffenseShowing(){const formation=cleanText(state.dcOffenseShowingFormation),setName=cleanText(state.dcOffenseShowingSet);return formation&&setName?{formation,set:setName}:null;}
function getOpponentOffenseFormationCatalog(){if(!DefenseRecommendationCore.buildOpponentOffenseFormationCatalog)return[];return DefenseRecommendationCore.buildOpponentOffenseFormationCatalog(state.normalizedPlays||[],normalizeOpponentTeam(state.selectedOpponent));}
function clearDcOffenseShowing(options={}){state.dcOffenseShowingFormation="";state.dcOffenseShowingSet="";state.dcOffenseShowingExpanded="";if(options.trace!==false)recordTraceEvent("dc-offense-showing-cleared",{at:new Date().toISOString(),opponent:normalizeOpponentTeam(state.selectedOpponent)||null,role:"dc"});if(options.render!==false)render();}
