function computeDcRecommendations(){if(!DefenseRecommendationCore.computeDefensiveRecommendations){return [];}const result=DefenseRecommendationCore.computeDefensiveRecommendations({plays:getTeamDefensivePlaybook(state.selectedTeam),down:state.down,yards:state.yards,goalToGo:state.goalToGo,fieldPosition:state.fieldPosition,recentPlayIds:state.dcRecentPlays||[],offenseShowing:getDcOffenseShowing()});return Array.isArray(result?.recommendations)?result.recommendations:[];}
function getDcRecommendationSetKey(displayed=getDisplayedDcRecommendations()){return displayed.slice(0,3).map(play=>play?.id).filter(Boolean).join("|");}
function confirmDcRecommendedPlay(playId){const displayed=getDisplayedDcRecommendations(),recommendationSetKey=getDcRecommendationSetKey(displayed);if(!cleanText(playId)||!state.selectedTeam||!recommendationSetKey)return;const matchIndex=displayed.findIndex(play=>play?.id===playId);const match=matchIndex>=0?displayed[matchIndex]:null;if(!match?.id)return;const alreadyCommittedThisSheet=state.dcUsageCommittedForSetKey===recommendationSetKey;const previousPenalty=state.dcPendingPenalty&&PenaltyCatalog.normalizePenaltyStamp?PenaltyCatalog.normalizePenaltyStamp(state.dcPendingPenalty):null;state.confirmedDcBasePlay=match;state.dcAudiblePlayId="";state.confirmedDcRecommendationId=match.id;state.confirmedDcRecommendationSetKey=recommendationSetKey;state.dcPendingPenalty=previousPenalty;if(!alreadyCommittedThisSheet){state.dcRecentPlays=[...(state.dcRecentPlays||[]),match.id].slice(-12);state.dcUsageCommittedForSetKey=recommendationSetKey;}recordTraceEvent("dc-play-confirmed",{playId:match.id,playName:match.play_name,type:match.type,formation:match.formation,set:match.set,rank:matchIndex+1,usageCommittedEarly:!alreadyCommittedThisSheet,penaltyPreserved:previousPenalty?previousPenalty.id:null,role:"dc"});setStatus("Defense call confirmed");render();}
function notifyOcrExactCallStateChanged(){try{if(typeof window.GridironOcrUi?.onExactCallStateChanged==="function")window.GridironOcrUi.onExactCallStateChanged(getOcrExactCallState());}catch(_err){}}
function beginOcrDefensiveSnap(situation){const key=JSON.stringify([situation.down,situation.yards,situation.goalToGo===true,situation.fieldPosition?.side,situation.fieldPosition?.yardLine]);if(state.ocrDcSnapSpot===key)return;state.ocrDcSnapSpot=key;state.confirmedOcrExactSetKey="";state.confirmedDcRecommendationId=null;state.confirmedDcRecommendationSetKey="";state.confirmedDcBasePlay=null;state.dcAudiblePlayId="";state.dcPendingPenalty=null;state.dcUsageCommittedForSetKey="";notifyOcrExactCallStateChanged();}
function getOcrExactCallState(){const setKey=getOcrExactSetKey();const sheetConfirmed=!!setKey&&state.confirmedOcrExactSetKey===setKey&&!!state.confirmedDcRecommendationId;const basePlay=state.confirmedDcBasePlay;const loggedId=state.dcAudiblePlayId||state.confirmedDcRecommendationId||basePlay?.id||"";const loggedPlay=(state.normalizedDefensivePlays||[]).find(play=>play.id===loggedId)||basePlay;const audibleFromBase=sheetConfirmed&&state.dcAudiblePlayId&&basePlay&&state.dcAudiblePlayId!==basePlay.id;let loggedText="";if(sheetConfirmed){loggedText=audibleFromBase?("Logged: "+cleanText(loggedPlay?.play_name).toUpperCase()+" (audible from "+cleanText(basePlay.play_name).toUpperCase()+")"):("Logged: "+(cleanText(loggedPlay?.play_name).toUpperCase()||"PLAY"));const penaltyLabel=state.dcPendingPenalty&&PenaltyCatalog.formatPenaltyBarLabel?PenaltyCatalog.formatPenaltyBarLabel(state.dcPendingPenalty):"";if(penaltyLabel)loggedText+=" · "+penaltyLabel;}return{setKey,sheetConfirmed,confirmedPlayId:sheetConfirmed?state.confirmedDcRecommendationId:null,loggedText,audiblePlayId:state.dcAudiblePlayId||"",penalty:state.dcPendingPenalty||null};}
function presentOcrExactPlays(recommendations=[]){const rows=(Array.isArray(recommendations)?recommendations:[]).map(entry=>{if(!entry)return null;const play=entry.play&&typeof entry.play==="object"?entry.play:entry;if(!play?.id)return null;return{play,why:cleanText(entry.why||entry._why||""),score:Number(entry._score??entry.score)||0};}).filter(Boolean).slice(0,3);const nextKey=rows.map(item=>item.play.id).join("|");const prevKey=getOcrExactSetKey();state.presentedOcrExactPlays=rows;if(rows.length&&nextKey&&nextKey!==prevKey){const shownIds=rows.map(item=>item.play.id);state.ocrExactExposurePlays=[...(state.ocrExactExposurePlays||[]),...shownIds].slice(-120);state.ocrExactExposureSheets=[...(state.ocrExactExposureSheets||[]),shownIds];}if(nextKey!==prevKey||!nextKey){state.confirmedOcrExactSetKey="";if(prevKey&&state.confirmedDcRecommendationSetKey===prevKey){state.confirmedDcRecommendationId=null;state.confirmedDcRecommendationSetKey="";state.confirmedDcBasePlay=null;state.dcAudiblePlayId="";}}notifyOcrExactCallStateChanged();if((Number(state._renderDepth)||0)>0){renderDcRecommendationCard();}else{render();}return getOcrExactCallState();}
function getOcrExactVarietyMemory(){return{recentPlayIds:[...(state.dcRecentPlays||[])],exposurePlayIds:[...(state.ocrExactExposurePlays||[])],exposureSheets:(state.ocrExactExposureSheets||[]).map(sheet=>[...sheet])};}
