function openOcrAudiblePicker(){if(!isOcrExactSheetActive()||!isDcPendingSnapReady())return false;openDcAudiblePicker();return true;}
function openOcrPenaltyPicker(){if(!isOcrExactSheetActive()||!isDcPendingSnapReady())return false;openDcPenaltyPicker();return true;}
function openDcAudiblePicker(){if(!isDcPendingSnapReady())return;state.audiblePickerMode="dc";if(dom.audibleSearchInput)dom.audibleSearchInput.value="";renderAudiblePickerList();if(dom.audibleOverlay){dom.audibleOverlay.classList.remove("hidden");dom.audibleOverlay.setAttribute("aria-hidden","false");}}
function applyDcAudiblePlay(playId){const basePlay=state.confirmedDcBasePlay;const audiblePlay=(state.normalizedDefensivePlays||[]).find(play=>play.id===playId);const sheetKey=getDcActiveSheetKey();if(!audiblePlay?.id||!basePlay?.id||!state.selectedTeam||!sheetKey)return;if(!isDcPendingSnapReady())return;if(formationSetKeyOf(audiblePlay)!==formationSetKeyOf(basePlay))return;const previousLoggedId=state.dcAudiblePlayId||basePlay.id;if(audiblePlay.id===previousLoggedId){closeAudiblePicker();return;}if(state.dcUsageCommittedForSetKey===sheetKey){const next=[...(state.dcRecentPlays||[])];for(let i=next.length-1;i>=0;i-=1){if(next[i]===previousLoggedId){next[i]=audiblePlay.id;break;}}state.dcRecentPlays=next.slice(-12);}state.dcAudiblePlayId=audiblePlay.id===basePlay.id?"":audiblePlay.id;recordTraceEvent("dc-play-audible",{at:new Date().toISOString(),fromPlayId:previousLoggedId,toPlayId:audiblePlay.id,formationSetKey:formationSetKeyOf(audiblePlay),role:"dc",packageMode:ENABLE_DC_V2_PACKAGES});closeAudiblePicker();notifyOcrExactCallStateChanged();render();}function openDcPenaltyPicker(){if(!isDcPendingSnapReady())return;state.penaltyPickerMode="dc";renderPenaltyPickerList();if(dom.penaltyOverlay){dom.penaltyOverlay.classList.remove("hidden");dom.penaltyOverlay.setAttribute("aria-hidden","false");}}
