function describeRecommendation(play,plan,traits,ctx){const reasons=[];if(plan.sticksRequired&&traits.sticksFriendly)reasons.push("good access to the sticks");if(traits.quickAnswer)reasons.push("gives a quick answer");if(traits.chunkCapable&&plan.idealGainMin>=7)reasons.push("can reach the needed chunk");if(traits.interiorRun&&["third_short","fourth_short","goal_to_go_tight"].includes(plan.situationBucket))reasons.push("fits a downhill short-yardage spot");if(plan.fieldPositionBucket==="backed_up")reasons.push("protects you when backed up");if(["red_zone","high_red_zone"].includes(plan.fieldPositionBucket))reasons.push("fits compressed red-zone space");const scoutHint=summarizeOpponentScoutingHint(play,ctx,state.userLearning,state.gameScoutingLog);if(scoutHint)reasons.push(scoutHint);if(!reasons.length)reasons.push("matches the current coordinator plan");return`${reasons.join(", ")}.`;}
