async function refreshRecommendationsClassic(){return computeRecommendations();}
function settlePendingOcSnap(nextSituation){
  if(state.coordinatorRole===COORDINATOR_ROLE_DC)return;
  const pendingContext=state.pendingOutcome;
  const nextDown=Number(nextSituation?.down);
  const nextYards=hasKnownNumericValue(nextSituation?.yardsToGo)?Number(nextSituation.yardsToGo):(hasKnownNumericValue(nextSituation?.yards)?Number(nextSituation.yards):null);
  const nextGoal=nextSituation?.goalToGo===true;
  const nextField=nextSituation?.fieldPosition||createEmptyFieldPosition();
  const pendingPenaltyStamp=pendingContext?.penalty&&PenaltyCatalog.normalizePenaltyStamp?PenaltyCatalog.normalizePenaltyStamp(pendingContext.penalty):null;
  const isVoidPenalty=pendingPenaltyStamp&&PenaltyCatalog.isVoidSnapPenalty&&PenaltyCatalog.isVoidSnapPenalty(pendingPenaltyStamp);
  const isSkipLearnPenalty=pendingPenaltyStamp&&pendingPenaltyStamp.effect===PenaltyCatalog.EFFECT_SKIP_LEARN;
  if(isVoidPenalty&&pendingContext){
    const voidPlay=(state.normalizedPlays||[]).find(play=>play.id===pendingContext.playId)||state.confirmedBasePlay||{id:pendingContext.playId,type:pendingContext.type,play_name:pendingContext.playName};
    undoLastCommittedUsage(voidPlay);
    state.confirmedPlayUsage=null;
    state.usageCommittedForSetKey="";
    if(state.sessionReport&&CoordinatorReport.attachPenalty){state.sessionReport=CoordinatorReport.attachPenalty(state.sessionReport,pendingPenaltyStamp,pendingContext.playId);}
    recordTraceEvent("learning-skip",{reason:"penalty_void",playId:pendingContext.playId,family:pendingContext.family,learningSituationKey:pendingContext.learningSituationKey,penaltyId:pendingPenaltyStamp.id,effect:pendingPenaltyStamp.effect,nextDown,nextYardsToGo:nextYards,nextGoalToGo:nextGoal,nextFieldPosition:nextField,outcome:null});
    state.pendingOutcome=null;
    return;
  }
  if(isSkipLearnPenalty&&pendingContext){
    const neutralOutcome=PenaltyCatalog.buildPenaltyOutcome?PenaltyCatalog.buildPenaltyOutcome(pendingPenaltyStamp):null;
    if(state.sessionReport&&CoordinatorReport.attachPenalty){state.sessionReport=CoordinatorReport.attachPenalty(state.sessionReport,pendingPenaltyStamp,pendingContext.playId);}
    if(neutralOutcome)recordSessionOutcome(neutralOutcome,pendingContext.playId);
    recordTraceEvent("learning-skip",{reason:"penalty_skip_learn",playId:pendingContext.playId,family:pendingContext.family,learningSituationKey:pendingContext.learningSituationKey,penaltyId:pendingPenaltyStamp.id,effect:pendingPenaltyStamp.effect,nextDown,nextYardsToGo:nextYards,nextGoalToGo:nextGoal,nextFieldPosition:nextField,outcome:neutralOutcome});
    commitConfirmedPlayUsage();
    state.pendingOutcome=null;
    return;
  }
  const outcome=inferPendingOutcome(pendingContext,{down:nextDown,yardsToGo:nextYards,goalToGo:nextGoal,fieldPosition:nextField});
  if(pendingContext)recordTraceEvent(outcome?"learning-outcome":"learning-skip",{playId:pendingContext.playId,family:pendingContext.family,learningSituationKey:pendingContext.learningSituationKey,nextDown,nextYardsToGo:nextYards,nextGoalToGo:nextGoal,nextFieldPosition:nextField,outcome});
  if(outcome&&pendingContext){
    recordSessionOutcome(outcome,pendingContext.playId);
    state.userLearning=recordUserLearningOutcome(state.userLearning,pendingContext,outcome);
    saveUserLearning();
    if(RecommendationCore.recordGameOutcomeMemoryEntry){
      state.driveOutcomeMemory=RecommendationCore.recordGameOutcomeMemoryEntry(state.driveOutcomeMemory,pendingContext,outcome,{maxEntries:12});
      state.gameOutcomeMemory=RecommendationCore.recordGameOutcomeMemoryEntry(state.gameOutcomeMemory,pendingContext,outcome,{maxEntries:24});
    }
  }
  commitConfirmedPlayUsage();
  state.pendingOutcome=null;
}
