function logOcrPreviousDefense(situation){if(state.coordinatorRole===COORDINATOR_ROLE_DC)return;const pending=state.pendingOutcome;if(!pending?.playId)return;const pendingYards=hasKnownNumericValue(pending.yardsToGo)?Number(pending.yardsToGo):null,stateYards=hasKnownNumericValue(state.yards)?Number(state.yards):null,pendingMatches=Number(pending.down)===Number(state.down)&&pendingYards===stateYards&&(pending.goalToGo===true)===(state.goalToGo===true)&&cleanText(pending.fieldPosition?.side)===cleanText(state.fieldPosition?.side)&&Number(pending.fieldPosition?.yardLine||0)===Number(state.fieldPosition?.yardLine||0);if(!pendingMatches)return;const nextDown=Number.isFinite(Number(situation.down))&&Number(situation.down)>=1?Number(situation.down):Number(state.down),nextYards=Number.isFinite(Number(situation.yards))&&Number(situation.yards)>0?Number(situation.yards):state.yards,nextGoal=situation.goalToGo!=null?!!situation.goalToGo:state.goalToGo===true,nextField=situation.fieldPosition&&hasKnownFieldPosition(situation.fieldPosition)?normalizeFieldPosition(situation.fieldPosition.side,situation.fieldPosition.yardLine):state.fieldPosition,spotChanged=nextDown!==Number(state.down)||(hasKnownNumericValue(nextYards)?Number(nextYards):null)!==stateYards||nextGoal!==(state.goalToGo===true)||cleanText(nextField?.side)!==cleanText(state.fieldPosition?.side)||Number(nextField?.yardLine||0)!==Number(state.fieldPosition?.yardLine||0);if(!spotChanged)return;const defense=normalizeDefenseLogValue(situation.previousDefensePlayName);if(defense===SCORING_DEFENSE_UNKNOWN)return;setLastDefenseShown(defense);}
